CREATE DATABASE IF NOT EXISTS aquapure CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aquapure;
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT,category VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,stock INT NOT NULL DEFAULT 0,image_url VARCHAR(500) DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INT AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(150),delivery_address TEXT NOT NULL,notes TEXT,subtotal DECIMAL(12,2) NOT NULL,status ENUM('Pending','Confirmed','Out for delivery','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NULL,product_name VARCHAR(120) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
